def transform(grid):
    """Combine the four 4x4 color masks, with priority 9 > 4 > 8 > 5."""
    colors = ((9, 10), (4, 15), (8, 0), (5, 5))
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            value = 0
            for color, start in colors:
                if grid[r][start + c] == color:
                    value = color
                    break
            row.append(value)
        out.append(row)
    return out
